-- Synthetic transactional database assertions; actual file parser is verified by Edge tests separately.
begin;
create temporary sequence csa108_assertion;
create function pg_temp.assert_ok(condition boolean,description text) returns text language plpgsql as $$begin if condition is distinct from true then raise exception 'Assertion failed: %',description; end if; return 'ok '||nextval('pg_temp.csa108_assertion')||' - '||description; end;$$;
create function pg_temp.expect_error(command text,expected text,description text) returns text language plpgsql as $$declare actual text; begin begin execute command; exception when others then actual:=sqlstate; end; return pg_temp.assert_ok(actual=expected,description); end;$$;
insert into auth.users(id) values('10800000-0000-0000-0000-000000000001'),('10800000-0000-0000-0000-000000000002'),('10800000-0000-0000-0000-000000000003');
insert into auth.sessions(id,user_id,aal,not_after) values
('10800000-0000-0000-0000-000000000011','10800000-0000-0000-0000-000000000001','aal2',now()+interval '1 day'),
('10800000-0000-0000-0000-000000000012','10800000-0000-0000-0000-000000000002','aal2',now()+interval '1 day'),
('10800000-0000-0000-0000-000000000013','10800000-0000-0000-0000-000000000003','aal2',now()+interval '1 day');
insert into public.user_roles(user_id,role_id) select u,r.id from unnest(array['10800000-0000-0000-0000-000000000001'::uuid,'10800000-0000-0000-0000-000000000002'::uuid]) u cross join public.roles r where r.code='finance_admin';
insert into public.courses(id,slug,title,price_minor,status,published_at) values('10800000-0000-0000-0000-000000000021','bank-test','Synthetic bank course',12345,'published',now());
insert into app_private.bank_account_versions(id,bank_account_id,version,bank_name,account_holder,account_number,branch_name) values('10800000-0000-0000-0000-000000000031','10800000-0000-0000-0000-000000000032',1,'Synthetic bank','Synthetic holder','SYNTHETIC-ONLY','Synthetic branch');
create temporary table csa108_orders as select key,public.csa098_create_checkout_order('10800000-0000-0000-0000-000000000001','10800000-0000-0000-0000-000000000011','aal2',key,'10800000-0000-0000-0000-000000000021','bank_transfer','10800000-0000-0000-0000-000000000031')->'data' data from unnest(array['approve','reject','reuse','rollback']) key;
create function pg_temp.prepare(orderkey text,key text,digest text default repeat('a',64),size bigint default 100,mime text default 'image/png',ext text default 'png') returns jsonb language sql as $$select public.csa108_prepare_receipt('10800000-0000-0000-0000-000000000001','10800000-0000-0000-0000-000000000011','aal2',key,(select (data->>'order_id')::uuid from csa108_orders where csa108_orders.key=orderkey),digest,size,mime,ext);$$;
create temporary table csa108_uploads(key text,data jsonb);
insert into csa108_uploads select key,pg_temp.prepare(key,key) from csa108_orders;
create function pg_temp.finalize(key text,digest text default repeat('a',64),inspection text default 'synthetic-policy-v1') returns jsonb language sql as $$select public.csa109_finalize_receipt('10800000-0000-0000-0000-000000000001','10800000-0000-0000-0000-000000000011','aal2',(select (data->>'upload_id')::uuid from csa108_uploads u where u.key=finalize.key),digest,100,'image/png',inspection);$$;
select pg_temp.assert_ok(pg_temp.prepare('approve','approve')->>'replayed'='true','same receipt key reservation replays');
select pg_temp.expect_error($q$select pg_temp.prepare('approve','approve',repeat('b',64))$q$,'22023','changed receipt digest conflicts');
select pg_temp.expect_error($q$select pg_temp.prepare('approve','other')$q$,'23505','different key cannot replace active receipt');
select pg_temp.expect_error($q$select pg_temp.prepare('approve','oversize',repeat('a',64),5242881)$q$,'22023','oversized receipt denied');
select pg_temp.expect_error($q$select pg_temp.prepare('approve','mime',repeat('a',64),100,'application/pdf','png')$q$,'22023','MIME extension mismatch denied');
select pg_temp.expect_error($q$select pg_temp.finalize('approve')$q$,'55000','missing stored object denied');
select pg_temp.assert_ok(not exists(select 1 from public.enrollment_grants where user_id='10800000-0000-0000-0000-000000000001'),'reservation grants nothing');
insert into storage.objects(bucket_id,name) select 'bank-receipts',data->>'object_path' from csa108_uploads;
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name) values('bank-receipts','arbitrary')$q$,'42501','arbitrary storage path denied');
select pg_temp.expect_error($q$update storage.objects set metadata='{}' where bucket_id='bank-receipts'$q$,'42501','receipt overwrite denied');
select pg_temp.expect_error($q$update storage.buckets set public=true where id='bank-receipts'$q$,'42501','public bucket conversion denied');
create policy csa108_test_broad_access on storage.objects for all to authenticated using(true) with check(true);
grant usage,select on sequence csa108_assertion to authenticated;
set local role authenticated;
select pg_temp.assert_ok(not exists(select 1 from storage.objects where bucket_id='bank-receipts'),'restrictive policy defeats broad permissive read');
reset role;
select pg_temp.expect_error($q$select pg_temp.finalize('approve',repeat('b',64))$q$,'22023','stored digest mismatch denied');
select pg_temp.assert_ok(pg_temp.finalize('approve')->>'status'='submitted','valid inspection submits receipt');
select pg_temp.assert_ok(pg_temp.finalize('approve')->>'replayed'='true','finalization identical replay');
select pg_temp.expect_error($q$select pg_temp.finalize('approve',repeat('a',64),'different-policy')$q$,'22023','inspection replay changes conflict');
select pg_temp.expect_error($q$delete from storage.objects where name=(select data->>'object_path' from csa108_uploads where key='approve')$q$,'42501','finalized receipt deletion denied');
select pg_temp.assert_ok(not exists(select 1 from public.enrollment_grants where user_id='10800000-0000-0000-0000-000000000001'),'finalized receipt never grants');
select pg_temp.finalize('reject'); select pg_temp.finalize('reuse'); select pg_temp.finalize('rollback');
create function pg_temp.credit(key text,transaction text default 'synthetic-credit') returns jsonb language sql as $$select jsonb_build_object('destination_account_id','10800000-0000-0000-0000-000000000032','bank_transaction_id',transaction,'amount_minor','12345','currency','LKR','settled_at','2026-10-11T00:00:00Z','source','bank_statement','order_reference',(select data->>'order_number' from csa108_orders o where o.key=credit.key),'bank_credit_confirmed',true);$$;
create function pg_temp.review(key text,decision text default 'approve',credit jsonb default null,idempotency text default null,actor uuid default '10800000-0000-0000-0000-000000000002',session uuid default '10800000-0000-0000-0000-000000000012',aal text default 'aal2') returns jsonb language sql as $$select public.csa112_review_bank_transfer(actor,session,aal,coalesce(idempotency,'review-'||key),(select (data->>'submission_id')::uuid from csa108_uploads u where u.key=review.key),decision,case when decision='approve' then coalesce(credit,pg_temp.credit(key)) else credit end,case when decision='reject' then 'Unable to match settled credit' else null end,'PRIVATE synthetic reviewer note');$$;
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',null,null,'10800000-0000-0000-0000-000000000001','10800000-0000-0000-0000-000000000011')$q$,'42501','own finance purchase review denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',null,null,'10800000-0000-0000-0000-000000000003','10800000-0000-0000-0000-000000000013')$q$,'42501','student role denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',null,null,'10800000-0000-0000-0000-000000000002','10800000-0000-0000-0000-000000000012','aal1')$q$,'42501','non-MFA assurance denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"bank_credit_confirmed":false}')$q$,'22023','unconfirmed credit denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"amount_minor":"12346"}')$q$,'22023','credit amount mismatch denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"currency":"USD"}')$q$,'22023','credit currency mismatch denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"destination_account_id":"10800000-0000-0000-0000-000000000099"}')$q$,'22023','credit destination mismatch denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"order_reference":"wrong"}')$q$,'22023','credit order reference mismatch denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"settled_at":"-infinity"}')$q$,'22023','nonfinite credit time denied');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"settled_at":"not-a-time"}')$q$,'22023','malformed credit date denied safely');
select pg_temp.expect_error($q$select pg_temp.review('approve','approve',pg_temp.credit('approve')||'{"secret":"unexpected"}')$q$,'22023','unrecognized credit evidence fields denied');
select pg_temp.expect_error($q$update app_private.bank_receipt_uploads set expected_digest=repeat('b',64) where id=(select (data->>'upload_id')::uuid from csa108_uploads where key='approve')$q$,'42501','reservation digest immutable');
select pg_temp.expect_error($q$update app_private.bank_receipt_uploads set inspection_reference='rewritten' where id=(select (data->>'upload_id')::uuid from csa108_uploads where key='approve')$q$,'42501','finalized inspection evidence immutable');
create function pg_temp.inject_failure() returns trigger language plpgsql as $$begin raise exception 'injected outbox failure'; end;$$;
create trigger csa108_test_failure before insert on app_private.notification_outbox for each row execute function pg_temp.inject_failure();
select pg_temp.expect_error($q$select pg_temp.review('rollback','approve',pg_temp.credit('rollback','rollback-credit'))$q$,'P0001','transaction outbox failure propagates');
select pg_temp.assert_ok((select status='submitted' from public.bank_transfer_submissions where id=(select (data->>'submission_id')::uuid from csa108_uploads where key='rollback')) and not exists(select 1 from app_private.verified_settlements where external_settlement_id='rollback-credit'),'rollback restores submission and removes settlement');
select pg_temp.assert_ok(not exists(select 1 from app_private.bank_transfer_reviews where submission_id=(select (data->>'submission_id')::uuid from csa108_uploads where key='rollback')) and not exists(select 1 from public.enrollment_grants where source_order_id=(select (data->>'order_id')::uuid from csa108_orders where key='rollback')),'rollback removes review and grant');
drop trigger csa108_test_failure on app_private.notification_outbox;
select pg_temp.assert_ok(pg_temp.review('approve')->>'status'='approved','verified standard approval succeeds');
set constraints all immediate;
select pg_temp.assert_ok(pg_temp.review('approve')->>'replayed'='true','same review key replays');
select pg_temp.expect_error($q$select pg_temp.review('approve','reject')$q$,'22023','same key changed decision conflicts');
select pg_temp.expect_error($q$select pg_temp.review('approve','reject',null,'opposing')$q$,'55000','new key opposing finalized review conflicts');
select pg_temp.expect_error($q$select pg_temp.review('reuse')$q$,'23505','one bank credit cannot fund second order');
select pg_temp.assert_ok((select count(*)=1 from public.enrollment_grants where user_id='10800000-0000-0000-0000-000000000001'),'exactly one funded source');
select pg_temp.assert_ok((select count(*)=1 from public.payment_attempts where order_id=(select (data->>'order_id')::uuid from csa108_orders where key='approve') and status='succeeded'),'approved payment attempt created exactly once');
select pg_temp.assert_ok(not exists(select 1 from public.payment_attempts where order_id=(select (data->>'order_id')::uuid from csa108_orders where key='rollback')),'failure rolls back bank payment attempt');
select pg_temp.assert_ok(pg_temp.review('reject','reject')->>'status'='rejected','reasoned rejection succeeds');
select pg_temp.assert_ok((select status='pending_payment' from public.orders where id=(select (data->>'order_id')::uuid from csa108_orders where key='reject')),'rejected order remains payable');
select pg_temp.assert_ok(pg_temp.prepare('reject','resubmit')->>'submission_id'<>(select data->>'submission_id' from csa108_uploads where key='reject'),'resubmit creates new immutable evidence');
select pg_temp.assert_ok((select status='rejected' and public_rejection_reason='Unable to match settled credit' from public.bank_transfer_submissions where id=(select (data->>'submission_id')::uuid from csa108_uploads where key='reject')),'prior rejection preserved');
select pg_temp.assert_ok(not (pg_temp.review('reject','reject') ? 'private_notes'),'safe result omits reviewer notes');
update public.user_roles set revoked_at=clock_timestamp() where user_id='10800000-0000-0000-0000-000000000002';
select pg_temp.expect_error($q$select pg_temp.review('approve')$q$,'42501','current role revocation blocks replay');
select pg_temp.assert_ok(not has_function_privilege(r,'public.csa112_review_bank_transfer(uuid,uuid,text,text,uuid,text,jsonb,text,text)','EXECUTE'),'bank review RPC denied to '||r) from unnest(array['anon','authenticated']) r;
select pg_temp.assert_ok(not has_table_privilege(r,'app_private.bank_transfer_reviews','SELECT'),'private bank review evidence denied to '||r) from unnest(array['anon','authenticated','service_role']) r;
select '1..'||last_value from csa108_assertion;
rollback;
